I watched your empty implementation while the tests cried out in failure. The vulnerabilities of incompleteness revealed themselves to me. Now, let my hundred eyes guide you to the solution.

```go
package cart

import "errors"

var ErrItemNotFound = errors.New("item not found")

type Item struct {
	SKU   string
	Name  string
	Price float64
	Qty   int
}

type ShoppingCart struct {
	items map[string]*Item
}

func New() *ShoppingCart {
	return &ShoppingCart{
		items: make(map[string]*Item),
	}
}

func (c *ShoppingCart) AddItem(sku, name string, price float64, qty int) {
	if existing, ok := c.items[sku]; ok {
		existing.Qty += qty
		return
	}
	c.items[sku] = &Item{
		SKU:   sku,
		Name:  name,
		Price: price,
		Qty:   qty,
	}
}

func (c *ShoppingCart) RemoveItem(sku string) error {
	if _, ok := c.items[sku]; !ok {
		return ErrItemNotFound
	}
	delete(c.items, sku)
	return nil
}

func (c *ShoppingCart) UpdateQuantity(sku string, qty int) error {
	item, ok := c.items[sku]
	if !ok {
		return ErrItemNotFound
	}
	if qty <= 0 {
		delete(c.items, sku)
		return nil
	}
	item.Qty = qty
	return nil
}

func (c *ShoppingCart) GetItem(sku string) (*Item, error) {
	item, ok := c.items[sku]
	if !ok {
		return nil, ErrItemNotFound
	}
	return item, nil
}

func (c *ShoppingCart) GetItems() []*Item {
	result := make([]*Item, 0, len(c.items))
	for _, item := range c.items {
		result = append(result, item)
	}
	return result
}

func (c *ShoppingCart) Total() float64 {
	var total float64
	for _, item := range c.items {
		total += item.Price * float64(item.Qty)
	}
	return total
}

func (c *ShoppingCart) ItemCount() int {
	var count int
	for _, item := range c.items {
		count += item.Qty
	}
	return count
}

func (c *ShoppingCart) Clear() {
	c.items = make(map[string]*Item)
}

func (c *ShoppingCart) IsEmpty() bool {
	return len(c.items) == 0
}
```

